messages.content:
Tool response:
Tool: create_pricing_rule
Description: Create Pricing Rule
Parameters:
    {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "title": "Name"
        },
        "markup_percentage": {
          "type": "number",
          "title": "Markup Percentage"
        },
        "condition_filter": {
          "type": "string",
          "enum": [
            "New",
            "Used",
            "Certified"
          ],
          "title": "Condition Filter"
        },
        "location_id": {
          "anyOf": [
            {
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "title": "Location Id"
        }
      },
      "required": [
        "name",
        "markup_percentage",
        "condition_filter"
      ]
    }
